#pragma once
// gguf-weights.h: load model weights from GGUF files
//
// GGUF weight loader for the backbone and the VAE.
// Both files are generated by convert.py.
//
// Usage:
//   GGUFModel gf;
//   if (!gf_load(&gf, "model.gguf")) { error; }
//   WeightCtx wctx;
//   wctx_init(&wctx, n_tensors);
//   ggml_tensor * w = gf_load_tensor(&wctx, gf, "layer.0.weight");
//   wctx_alloc(&wctx, backend);
//   gf_close(&gf);   // safe after wctx_alloc copied data to GPU

#include "gguf.h"
#include "weight-ctx.h"
#include "lora.h"  // Local addition

#include <atomic>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

#ifdef _WIN32
// NOMINMAX keeps the min and max macros out of every translation unit that
// reaches this header, WIN32_LEAN_AND_MEAN keeps winsock.h out so a server
// including winsock2.h stays free of the duplicate declarations.
#    ifndef NOMINMAX
#        define NOMINMAX
#    endif
#    ifndef WIN32_LEAN_AND_MEAN
#        define WIN32_LEAN_AND_MEAN
#    endif
#    include <windows.h>
#else
#    include <fcntl.h>
#    include <sys/mman.h>
#    include <sys/stat.h>
#    include <unistd.h>
#endif

struct GGUFModel {
    struct gguf_context * gguf;         // parsed header (KV + tensor metadata)
    struct ggml_context * meta;         // tensor descriptors (no data)
    uint8_t *             mapping;      // mmapped file
    size_t                file_size;
    size_t                data_offset;  // gguf_get_data_offset(gguf)
#ifdef _WIN32
    HANDLE fh;
    HANDLE mh;
#else
    int fd;
#endif
};

static void gf_close(GGUFModel * gf) {
    if (gf->gguf) {
        gguf_free(gf->gguf);
    }
    if (gf->meta) {
        ggml_free(gf->meta);
    }
#ifdef _WIN32
    if (gf->mapping) {
        UnmapViewOfFile(gf->mapping);
    }
    if (gf->mh) {
        CloseHandle(gf->mh);
    }
    if (gf->fh && gf->fh != INVALID_HANDLE_VALUE) {
        CloseHandle(gf->fh);
    }
#else
    if (gf->mapping) {
        munmap(gf->mapping, gf->file_size);
    }
    if (gf->fd >= 0) {
        close(gf->fd);
    }
#endif
    *gf = {};
}

static bool gf_load(GGUFModel * gf, const char * path) {
    *gf = {};

    // mmap the file
#ifdef _WIN32
    gf->fh = CreateFileA(path, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (gf->fh == INVALID_HANDLE_VALUE) {
        fprintf(stderr, "[GGUF] Cannot open %s\n", path);
        return false;
    }
    LARGE_INTEGER li;
    GetFileSizeEx(gf->fh, &li);
    gf->file_size = (size_t) li.QuadPart;
    gf->mh        = CreateFileMappingA(gf->fh, NULL, PAGE_READONLY, 0, 0, NULL);
    if (!gf->mh) {
        CloseHandle(gf->fh);
        fprintf(stderr, "[GGUF] CreateFileMapping failed %s\n", path);
        return false;
    }
    gf->mapping = (uint8_t *) MapViewOfFile(gf->mh, FILE_MAP_READ, 0, 0, 0);
    if (!gf->mapping) {
        CloseHandle(gf->mh);
        CloseHandle(gf->fh);
        fprintf(stderr, "[GGUF] MapViewOfFile failed %s\n", path);
        return false;
    }
#else
    gf->fd = open(path, O_RDONLY);
    if (gf->fd < 0) {
        fprintf(stderr, "[GGUF] Cannot open %s\n", path);
        return false;
    }
    struct stat sb;
    fstat(gf->fd, &sb);
    gf->file_size = (size_t) sb.st_size;
    gf->mapping   = (uint8_t *) mmap(NULL, gf->file_size, PROT_READ, MAP_PRIVATE, gf->fd, 0);
    if (gf->mapping == MAP_FAILED) {
        close(gf->fd);
        gf->mapping = NULL;
        fprintf(stderr, "[GGUF] Mmap failed %s\n", path);
        return false;
    }
#endif

    // Parse GGUF header, create tensor metadata context
    struct ggml_context *   meta   = NULL;
    struct gguf_init_params params = { /*no_alloc=*/true, /*ctx=*/&meta };
    gf->gguf                       = gguf_init_from_file(path, params);
    if (!gf->gguf) {
        fprintf(stderr, "[GGUF] Failed to parse %s\n", path);
        gf_close(gf);
        return false;
    }
    gf->meta        = meta;
    gf->data_offset = gguf_get_data_offset(gf->gguf);

    int64_t n = gguf_get_n_tensors(gf->gguf);

    // Verify every tensor fits inside the mapped file. Catches truncated
    // downloads early with a clear message instead of a segfault deep in
    // cuMemcpyHtoDAsync when the backend reads past the mmap.
    for (int64_t i = 0; i < n; i++) {
        const char *         tname = gguf_get_tensor_name(gf->gguf, i);
        struct ggml_tensor * t     = ggml_get_tensor(gf->meta, tname);
        size_t               toff  = gguf_get_tensor_offset(gf->gguf, i);
        size_t               tsize = ggml_nbytes(t);
        size_t               end   = gf->data_offset + toff + tsize;
        if (end > gf->file_size) {
            fprintf(stderr,
                    "[GGUF] FATAL: '%s' is truncated or corrupt\n"
                    "[GGUF] FATAL: tensor '%s' needs bytes [%zu..%zu) but file is only %zu bytes\n"
                    "[GGUF] FATAL: re-download the file and verify its size or checksum\n",
                    path, tname, gf->data_offset + toff, end, gf->file_size);
            gf_close(gf);
            return false;
        }
    }

    fprintf(stderr, "[GGUF] %s: %lld tensors, data at offset %zu\n", path, (long long) n, gf->data_offset);
    return true;
}

// Local addition: the LoRA set merged into weights as they load. The store sets
// it around one module's load; a merge that fails leaves its reason in
// g_gf_lora_error and the store throws that load away.
inline LoraSet *   g_gf_lora = nullptr;
inline std::string g_gf_lora_error;

static int64_t gf_lora_rows(void * ctx, const std::string & name, int64_t * cols) {
    const GGUFModel *    gf = static_cast<const GGUFModel *>(ctx);
    struct ggml_tensor * t  = ggml_get_tensor(gf->meta, name.c_str());
    if (!t) {
        return 0;
    }
    if (ggml_n_dims(t) == 1) {
        *cols = 1;
        return t->ne[0];
    }
    *cols = t->ne[0];
    return t->ne[1];
}

// The type a LoRA-merged weight is kept in: float types keep theirs; quantized
// ones become Q8_0, because a LoRA's change is often smaller than Q6_K/Q5_K
// rounding and would be lost by re-quantizing to them (measured: no closer to
// the merged weights than leaving the LoRA out, on the weights it barely moves).
static enum ggml_type gf_lora_type(enum ggml_type t) {
    return (t == GGML_TYPE_F32 || t == GGML_TYPE_BF16 || t == GGML_TYPE_F16) ? t : GGML_TYPE_Q8_0;
}

static bool gf_lora_hits(const GGUFModel & gf, const std::vector<std::string> & names) {
    if (!g_gf_lora) {
        return false;
    }
    std::string error;
    if (!lora_bind(g_gf_lora, gf_lora_rows, (void *) &gf, &error)) {
        if (g_gf_lora_error.empty()) {
            g_gf_lora_error = error;
        }
        return false;
    }
    for (const auto & n : names) {
        if (lora_touches(g_gf_lora, n)) {
            return true;
        }
    }
    return false;
}

static const void * gf_lora_stage(WeightCtx * wctx, const GGUFModel & gf, const std::string & name,
                                  const struct ggml_tensor * src, const void * raw, enum ggml_type want, size_t * nbytes,
                                  bool force);

// One part of a fused weight converted to `type` (merged if a LoRA touches it);
// on a failed merge a zero buffer keeps the offsets valid (the load is discarded)
static void gf_lora_push_part(WeightCtx * wctx, const GGUFModel & gf, struct ggml_tensor * fused, const std::string & name,
                              const struct ggml_tensor * src, const void * raw, enum ggml_type type, size_t at) {
    size_t       bytes  = 0;
    const void * merged = gf_lora_stage(wctx, gf, name, src, raw, type, &bytes, true);
    if (!merged) {
        bytes    = ggml_row_size(type, src->ne[0]) * (size_t) src->ne[1];
        auto buf = std::make_unique<float[]>((bytes + 3) / 4);
        merged   = buf.get();
        wctx->staging.push_back(std::move(buf));
    }
    wctx->pending.push_back({ fused, merged, bytes, at });
}

// When the set touches `name`: the merged tensor in `want` (F32, or the file's own
// type, re-quantized if need be) in a staging buffer, and its size; else NULL.
static const void * gf_lora_stage(WeightCtx * wctx, const GGUFModel & gf, const std::string & name,
                                  const struct ggml_tensor * src, const void * raw, enum ggml_type want, size_t * nbytes,
                                  bool force) {
    if (!g_gf_lora) {
        return NULL;
    }
    std::string error;
    if (!lora_bind(g_gf_lora, gf_lora_rows, (void *) &gf, &error)) {
        if (g_gf_lora_error.empty()) {
            g_gf_lora_error = error;
        }
        return NULL;
    }
    if (!lora_touches(g_gf_lora, name) && !force) {
        return NULL;
    }
    int64_t cols = 1, rows = gf_lora_rows((void *) &gf, name, &cols);
    size_t  n    = (size_t) (rows * cols);
    std::vector<LoraPrepared> ps;
    if (!lora_prepare(g_gf_lora, name, rows, cols, &ps, &error)) {
        if (g_gf_lora_error.empty()) {
            g_gf_lora_error = error;
        }
        return NULL;
    }
    if (want != GGML_TYPE_F32 && want != GGML_TYPE_BF16 && want != GGML_TYPE_F16 && ggml_quantize_requires_imatrix(want)) {
        if (g_gf_lora_error.empty()) {
            g_gf_lora_error = std::string("LoRAs cannot be merged into ") + ggml_type_name(want) +
                              " weights (re-quantizing needs an importance matrix); use a BF16, Q8_0, Q6_K or Q5_K_M model";
        }
        return NULL;
    }
    // One pass per block of rows, on several threads: decode, add, check, encode
    const size_t src_row = ggml_row_size(src->type, cols), out_row = ggml_row_size(want, cols);
    auto         f32     = std::make_unique<float[]>(n);
    size_t       bytes   = want == GGML_TYPE_F32 ? n * sizeof(float) : out_row * (size_t) rows;
    std::unique_ptr<float[]> out;
    if (want != GGML_TYPE_F32) {
        out = std::make_unique<float[]>((bytes + 3) / 4);
    }
    bool has_replace = false;
    for (const auto & p : ps) {
        has_replace |= p.kind == LoraGroup::REPLACE;
    }
    std::vector<float> base;
    if (has_replace) {
        base.resize(n);
    }
    std::atomic<bool> finite{ true };
    lora_parallel_rows(rows, [&](int64_t r0, int64_t r1) {
        float *      w   = f32.get() + r0 * cols;
        const char * in  = static_cast<const char *>(raw) + (size_t) r0 * src_row;
        int64_t      cnt = (r1 - r0) * cols;
        if (src->type == GGML_TYPE_F32) {
            memcpy(w, in, (size_t) cnt * sizeof(float));
        } else {
            ggml_get_type_traits(src->type)->to_float(in, w, cnt);
        }
        if (has_replace) {
            memcpy(base.data() + r0 * cols, w, (size_t) cnt * sizeof(float));
        }
        lora_apply_rows(ps, f32.get(), base.data(), r0, r1, cols);
        for (int64_t i = 0; i < cnt; i++) {
            if (!std::isfinite(w[i])) {
                finite = false;
                break;
            }
        }
        if (want == GGML_TYPE_BF16) {
            ggml_fp32_to_bf16_row(w, reinterpret_cast<ggml_bf16_t *>(out.get()) + r0 * cols, cnt);
        } else if (want == GGML_TYPE_F16) {
            ggml_fp32_to_fp16_row(w, reinterpret_cast<ggml_fp16_t *>(out.get()) + r0 * cols, cnt);
        } else if (want != GGML_TYPE_F32) {
            ggml_quantize_chunk(want, f32.get(), out.get(), r0 * cols, r1 - r0, cols, nullptr);
        }
    });
    if (!finite) {
        if (g_gf_lora_error.empty()) {
            g_gf_lora_error = "the merge made " + name + " non-finite; lower the strength";
        }
        return NULL;
    }
    if (want == GGML_TYPE_F32) {
        *nbytes             = bytes;
        const void * merged = f32.get();
        wctx->staging.push_back(std::move(f32));
        return merged;
    }
    *nbytes             = bytes;
    const void * merged = out.get();
    wctx->staging.push_back(std::move(out));
    return merged;
}

// Load a tensor from GGUF into the weight context.
// Returns ggml_tensor (not yet backed by memory; call wctx_alloc after all loads).
// Tensor shapes are already in ggml order (ne[0]=innermost).
static struct ggml_tensor * gf_load_tensor(WeightCtx *         wctx,
                                           const GGUFModel &   gf,
                                           const std::string & name,
                                           const int64_t *     shape_override  = nullptr,
                                           int                 n_dims_override = 0) {
    int64_t idx = gguf_find_tensor(gf.gguf, name.c_str());
    if (idx < 0) {
        fprintf(stderr, "[GGUF] FATAL: tensor '%s' not found\n", name.c_str());
        exit(1);
    }

    // Get metadata from the context populated by gguf_init_from_file
    struct ggml_tensor * src = ggml_get_tensor(gf.meta, name.c_str());
    if (!src) {
        fprintf(stderr, "[GGUF] FATAL: tensor '%s' not in meta context\n", name.c_str());
        exit(1);
    }
    int     n_dims;
    int64_t ne[4] = { 1, 1, 1, 1 };

    if (shape_override && n_dims_override > 0) {
        n_dims = n_dims_override;
        for (int i = 0; i < n_dims; i++) {
            ne[i] = shape_override[i];
        }
    } else {
        n_dims = ggml_n_dims(src);
        for (int i = 0; i < n_dims; i++) {
            ne[i] = src->ne[i];
        }
    }

    enum ggml_type       type   = gf_lora_hits(gf, { name }) ? gf_lora_type(src->type) : src->type;
    struct ggml_tensor * tensor = ggml_new_tensor(wctx->ctx, type, n_dims, ne);
    ggml_set_name(tensor, name.c_str());

    size_t       offset = gguf_get_tensor_offset(gf.gguf, idx);
    const void * data   = gf.mapping + gf.data_offset + offset;
    size_t       nbytes = ggml_nbytes(src);

    size_t       lora_bytes = 0;
    const void * merged     = gf_lora_stage(wctx, gf, name, src, data, type, &lora_bytes, type != src->type);
    wctx->pending.push_back({ tensor, merged ? merged : data, merged ? lora_bytes : nbytes, 0 });
    return tensor;
}

// Get raw pointer to tensor data in the mmapped file.
// Useful for CPU-side operations (e.g. bf16 embed lookup for lyrics).
// Returns NULL if not found.
static const void * gf_get_data(const GGUFModel & gf, const char * name) {
    int64_t idx = gguf_find_tensor(gf.gguf, name);
    if (idx < 0) {
        return NULL;
    }
    size_t offset = gguf_get_tensor_offset(gf.gguf, idx);
    return gf.mapping + gf.data_offset + offset;
}

// Load tensor, converting to F32 at load time (eliminates runtime cast nodes).
// Best for small tensors: norms [H], QK-norms [D], scale_shift_table [H,6], biases.
static struct ggml_tensor * gf_load_tensor_f32(WeightCtx * wctx, const GGUFModel & gf, const std::string & name) {
    int64_t idx = gguf_find_tensor(gf.gguf, name.c_str());
    if (idx < 0) {
        fprintf(stderr, "[GGUF] FATAL: tensor '%s' not found\n", name.c_str());
        exit(1);
    }
    struct ggml_tensor * src    = ggml_get_tensor(gf.meta, name.c_str());
    int                  n_dims = ggml_n_dims(src);
    int64_t              ne[4]  = { 1, 1, 1, 1 };
    for (int i = 0; i < n_dims; i++) {
        ne[i] = src->ne[i];
    }

    // If already F32, just load normally
    if (src->type == GGML_TYPE_F32) {
        return gf_load_tensor(wctx, gf, name);
    }

    // Bail early on types without a dequantizer (before creating tensor in ctx)
    const struct ggml_type_traits * traits = ggml_get_type_traits(src->type);
    if (!traits->to_float) {
        fprintf(stderr, "[GGUF] WARNING: gf_load_tensor_f32 unsupported type %d for '%s', loading as-is\n", src->type,
                name.c_str());
        return gf_load_tensor(wctx, gf, name);
    }

    // Create F32 tensor
    struct ggml_tensor * tensor = ggml_new_tensor(wctx->ctx, GGML_TYPE_F32, n_dims, ne);
    ggml_set_name(tensor, name.c_str());

    // Convert data into staging buffer. unique_ptr keeps .get() stable even
    // when wctx->staging grows on subsequent calls.
    size_t  n    = ggml_nelements(src);
    auto    buf  = std::make_unique<float[]>(n);
    float * data = buf.get();

    size_t       offset = gguf_get_tensor_offset(gf.gguf, idx);
    const void * raw    = gf.mapping + gf.data_offset + offset;

    traits->to_float(raw, data, (int64_t) n);
    if (g_gf_lora) {
        size_t lora_bytes = 0;
        if (const void * merged = gf_lora_stage(wctx, gf, name, src, raw, GGML_TYPE_F32, &lora_bytes, false)) {
            wctx->pending.push_back({ tensor, merged, lora_bytes, 0 });
            return tensor;
        }
    }

    wctx->pending.push_back({ tensor, data, n * sizeof(float), 0 });
    wctx->staging.push_back(std::move(buf));
    return tensor;
}

// Fuse Q, K, V projection weights into a single tensor [ne0, q_ne1 + k_ne1 + v_ne1].
// Works for any quantized type since quantization is per-row (along ne[0]).
// The fused tensor data is q rows || k rows || v rows (contiguous).
static struct ggml_tensor * gf_load_qkv_fused(WeightCtx *         wctx,
                                              const GGUFModel &   gf,
                                              const std::string & q_name,
                                              const std::string & k_name,
                                              const std::string & v_name) {
    struct ggml_tensor * q_src = ggml_get_tensor(gf.meta, q_name.c_str());
    struct ggml_tensor * k_src = ggml_get_tensor(gf.meta, k_name.c_str());
    struct ggml_tensor * v_src = ggml_get_tensor(gf.meta, v_name.c_str());
    if (!q_src || !k_src || !v_src) {
        fprintf(stderr, "[GGUF] FATAL: QKV tensor not found: %s / %s / %s\n", q_name.c_str(), k_name.c_str(),
                v_name.c_str());
        exit(1);
    }
    // All must share ne[0] (input dim) and type - otherwise can't fuse
    GGML_ASSERT(q_src->ne[0] == k_src->ne[0] && k_src->ne[0] == v_src->ne[0]);
    if (q_src->type != k_src->type || k_src->type != v_src->type) {
        return NULL;  // caller should fall back to separate loads
    }

    int64_t              ne0       = q_src->ne[0];
    int64_t              fused_ne1 = q_src->ne[1] + k_src->ne[1] + v_src->ne[1];
    int64_t              ne[2]     = { ne0, fused_ne1 };
    enum ggml_type       type      = q_src->type;
    if (gf_lora_hits(gf, { q_name, k_name, v_name })) {
        type = gf_lora_type(type);   // Local addition: one type for all three parts
    }
    struct ggml_tensor * fused     = ggml_new_tensor(wctx->ctx, type, 2, ne);

    size_t row_size = ggml_row_size(q_src->type, ne0);
    size_t q_bytes  = q_src->ne[1] * row_size;
    size_t k_bytes  = k_src->ne[1] * row_size;
    size_t v_bytes  = v_src->ne[1] * row_size;

    auto get_data = [&](const std::string & name) -> const void * {
        int64_t idx = gguf_find_tensor(gf.gguf, name.c_str());
        size_t  off = gguf_get_tensor_offset(gf.gguf, idx);
        return gf.mapping + gf.data_offset + off;
    };

    if (type != q_src->type) {   // re-typed for a LoRA: every part converted, merged or not
        size_t out_row = ggml_row_size(type, ne0);
        gf_lora_push_part(wctx, gf, fused, q_name, q_src, get_data(q_name), type, 0);
        gf_lora_push_part(wctx, gf, fused, k_name, k_src, get_data(k_name), type, (size_t) q_src->ne[1] * out_row);
        gf_lora_push_part(wctx, gf, fused, v_name, v_src, get_data(v_name), type,
                          (size_t) (q_src->ne[1] + k_src->ne[1]) * out_row);
        return fused;
    }
    auto part = [&](const std::string & name, const struct ggml_tensor * src, size_t bytes, size_t at) {
        size_t       lora_bytes = 0;
        const void * raw        = get_data(name);
        const void * merged     = gf_lora_stage(wctx, gf, name, src, raw, src->type, &lora_bytes, false);
        wctx->pending.push_back({ fused, merged ? merged : raw, merged ? lora_bytes : bytes, at });
    };
    part(q_name, q_src, q_bytes, 0);
    part(k_name, k_src, k_bytes, q_bytes);
    part(v_name, v_src, v_bytes, q_bytes + k_bytes);
    return fused;
}

// Fuse two projection weights [ne0, a_ne1 + b_ne1] when types match.
// Returns NULL if types differ.
static struct ggml_tensor * gf_load_pair_fused(WeightCtx *         wctx,
                                               const GGUFModel &   gf,
                                               const std::string & a_name,
                                               const std::string & b_name) {
    struct ggml_tensor * a_src = ggml_get_tensor(gf.meta, a_name.c_str());
    struct ggml_tensor * b_src = ggml_get_tensor(gf.meta, b_name.c_str());
    if (!a_src || !b_src) {
        return NULL;
    }
    if (a_src->ne[0] != b_src->ne[0] || a_src->type != b_src->type) {
        return NULL;
    }

    int64_t              ne0   = a_src->ne[0];
    int64_t              ne[2] = { ne0, a_src->ne[1] + b_src->ne[1] };
    enum ggml_type       type  = a_src->type;
    if (gf_lora_hits(gf, { a_name, b_name })) {
        type = gf_lora_type(type);   // Local addition: one type for both parts
    }
    struct ggml_tensor * fused = ggml_new_tensor(wctx->ctx, type, 2, ne);

    size_t row_size = ggml_row_size(a_src->type, ne0);
    size_t a_bytes  = a_src->ne[1] * row_size;
    size_t b_bytes  = b_src->ne[1] * row_size;

    auto get_data = [&](const std::string & name) -> const void * {
        int64_t idx = gguf_find_tensor(gf.gguf, name.c_str());
        size_t  off = gguf_get_tensor_offset(gf.gguf, idx);
        return gf.mapping + gf.data_offset + off;
    };

    if (type != a_src->type) {   // re-typed for a LoRA: both parts converted, merged or not
        gf_lora_push_part(wctx, gf, fused, a_name, a_src, get_data(a_name), type, 0);
        gf_lora_push_part(wctx, gf, fused, b_name, b_src, get_data(b_name), type,
                          (size_t) a_src->ne[1] * ggml_row_size(type, ne0));
        return fused;
    }
    auto part = [&](const std::string & name, const struct ggml_tensor * src, size_t bytes, size_t at) {
        size_t       lora_bytes = 0;
        const void * raw        = get_data(name);
        const void * merged     = gf_lora_stage(wctx, gf, name, src, raw, src->type, &lora_bytes, false);
        wctx->pending.push_back({ fused, merged ? merged : raw, merged ? lora_bytes : bytes, at });
    };
    part(a_name, a_src, a_bytes, 0);
    part(b_name, b_src, b_bytes, a_bytes);
    return fused;
}

// Read a string KV value (returns "" if not found)
static const char * gf_get_str(const GGUFModel & gf, const char * key) {
    int64_t idx = gguf_find_key(gf.gguf, key);
    if (idx < 0) {
        return "";
    }
    return gguf_get_val_str(gf.gguf, idx);
}
